# Compute the discriminant of the linear system generated by pols via
# naive elimination.
function naive_elimination(pols)
    K = base_ring(pols[1])
    m = length(gens(parent(pols[1]))) - 1
    n = length(pols) - 1
    RR, Z, X = polynomial_ring(K, :Z => 1:n+1, :X => 1:m+1)
    f = sum([Z[i] * evaluate(pols[i], X) for i = 1:n+1])
    J = ideal([derivative(f, xx) for xx in X])
    println("saturating...")
    J = saturation(J, ideal(X))
    println("eliminating...")
    E = eliminate(J, X)
    println("done!")
    disc = gens(E)[1]
    S, Z = graded_polynomial_ring(K, :Z => 0:n)
    return evaluate(disc, [Z; zeros(S, length(X))])
end

# Compute the discriminant of the linear system generated by pols via
# naive elimination. Saturation is replaced by elimination on each affine chart.
function naive_elimination_no_saturation(pols)
    K = base_ring(pols[1])
    m = length(gens(parent(pols[1]))) - 1
    n = length(pols) - 1
    RR, Z, X = polynomial_ring(K, :Z => 1:n+1, :X => 1:m+1)
    f = sum([Z[i] * evaluate(pols[i], X) for i = 1:n+1])
    J = ideal([derivative(f, xx) for xx in X])
    E = ideal(RR(1))
    println("elimination on each chart...")
    for i = 1:m+1
        println("chart X[$i] = 1")
        EE = eliminate(J + ideal(X[i] - 1), X)
        E = intersect(E, EE)
    end
    println("done!")
    disc = gens(E)[1]
    S, Z = graded_polynomial_ring(K, :Z => 0:n)
    return evaluate(disc, [Z; zeros(S, length(X))])
end

# Compute the component pr_2(Y_1)
function get_prY1(pols)
    K = base_ring(pols[1])
    m = length(gens(parent(pols[1]))) - 1
    n = length(pols) - 1
    RR, Z, X = polynomial_ring(K, :Z => 1:n+1, :X => 1:m+1)
    f = sum([Z[i] * evaluate(pols[i], X) for i = 1:n+1])
    g = [derivative(f, xx) for xx in X]
    IM = identity_matrix(ZZ, length(Z))
    IM = [Int(m) for m in IM]
    mat = transpose(reshape([coeff(g[i], Z, IM[j, :]) for i = 1:m+1 for j = 1:n+1], n + 1, m + 1))
    mat = matrix_space(RR, size(mat)...)(mat)
    minorideal = ideal(minors(mat, rank(mat)))
    MP = minimal_primes(minorideal)
    E = ideal(RR(1))
    for mp in MP
        for i = 1:m+1
            J = mp + ideal(g) + ideal(X[i] - 1)
            EE = eliminate(J, X)
            for EEE in minimal_primes(EE)
                if dim(EEE) == m + 1 + n
                    E = intersect(E, EEE)
                end
            end
        end
    end
    facE = collect(factor(gens(E)[1]))
    S, Z = graded_polynomial_ring(K, :Z => 0:n)
    return [evaluate(ff[1], [Z; zeros(S, length(X))]) for ff in facE]
end

