        "Z2" => [w^3, z * w^2, x * w^2 + y * w^2, z^2 * w, x * z * w + y * z * w, x^2 * w + y^2 * w, x * y * w, z^3, x * z^2 + y * z^2, x^2 * z + y^2 * z, x * y * z, x^3 + y^3, x^2 * y + x * y^2],
