# get a basis for the linear system of invariant cubics under the action of the group "groupname".
# run all_groupnames() to see all possible inputs.
function get_basis(groupname,table; K=QQ)
    if table == "T1"
        data = get_dict_T1(; K=K)
    elseif table == "T1_lines"
        data = get_dict_T1_lines(; K=K)
    elseif table == "T3"
        data = get_dict_T3(; K=K)
    elseif table == "T3_lines"
        data = get_dict_T3_lines(; K=K)
    elseif table == "T4"
        data = get_dict_T4(; K=K)
    elseif table == "T4_lines"
        data = get_dict_T4_lines(; K=K)
    elseif table == "T8"
	data = get_dict_T8(; K=K)
    elseif table == "T8_lines"
	data = get_dict_T8_lines(; K=K)
    end
    return get(data, groupname, [])
end

# returns a list of all groups for which a list of invariants is hard coded.
function all_groupnames(table)
    R, vrs = polynomial_ring(QQ, ["x"; "y"; "z"; "w"])
    x, y, z, w = vrs
    if table == "T1"
        data = get_dict_T1()
    elseif table == "T1_lines"
        data = get_dict_T1_lines()
    elseif table == "T3"
        data = get_dict_T3()
    elseif table == "T3_lines"
        data = get_dict_T3_lines()
    elseif table == "T4"
        data = get_dict_T4()
    elseif table == "T4_lines"
        data = get_dict_T4_lines()
    elseif table == "T8"
        data = get_dict_T8()
    elseif table == "T8_lines"
        data = get_dict_T8_lines()
    end
    return collect(keys(data))
end

# Parametrize the component of the discriminant coming from Y0.
function param_prY0(pols)
    K = base_ring(pols[1])
    R = parent(pols[1])
    vrs = gens(R)
    m = length(vrs) - 1
    n = length(pols) - 1
    Jh = hcat([[derivative(p, v) for v in vrs] for p in pols]...)
    Jh = matrix_space(R, size(Jh)...)(Jh)
    r = rank(Jh)
    S, x, v = polynomial_ring(R, :x => 1:m+1, :v => 1:n+1-r)
    phi = hom(R, S, x)
    Jh = matrix_space(S, size(Jh)...)([phi(j) for j in Jh])
    Kh = nullspace(Jh)[2]
    if size(Kh, 2) > 0
        return Kh * v
    else
        #println("Y0 is empty")
        return []
    end
end

# Compute the dimension of the component of the discriminant coming from Y0
# (as a subvariety of P^n)
function dim_prY0(pols)
    param = param_prY0(pols)
    if isempty(param)
        return -1
    end
    R = parent(param[1])
    vrs = gens(R)
    J = hcat([[derivative(p, v) for v in vrs] for p in param]...)
    J = matrix_space(R, size(J)...)(J)
    randpt = rand(-1000:1000, length(vrs))
    K = base_ring(pols[1])
    Jval = [evaluate(j, randpt) for j in J]
    Jval = matrix_space(R, size(J)...)(Jval)
    if rank(Jval) == length(pols) - 1
        return rank(Jval) - 1
    else
        return rank(J) - 1
    end
end

# Compute a polynomial with monomial support "mons" which interpolates the samples in "samples".
function get_interpolant(samples, mons)
    K = parent(samples[1][1])
    S, Z = graded_polynomial_ring(K, :Z => 0:length(samples[1])-1)
    b = mons
    b = [Int64.(bb) for bb in b]
    smtx = hcat(samples...)
    Vdm = transpose(vcat([prod(smtx .^ bb, dims=1) for bb in b]...))
    NS = nullspace(matrix_space(K, size(Vdm)...)(Vdm))[2]
    if size(NS, 2) > 0
        println("interpolant found")
        println("nullspace has dimension $(size(NS,2))")
        if size(NS, 2) == 1
            mons = [prod([Z[i]^bb[i] for i = 1:length(bb)]) for bb in b]
            if K == QQ
                NS = lcm([u for u in denominator.(NS)]) * NS
            end
            disc = sum([NS[i] * mons[i] for i = 1:length(mons)])
            return disc, true
        else
            return [], false
        end
    else
        return [], false
    end
end

# Try to prove that "disc" is the irreducible defining equation of pr_2(Y0) for the linear system pols.
function certify_prY0(disc, pols)
    p = param_prY0(pols)
    K = base_ring(pols[1])
    e = evaluate(disc, p)
    if length(factor(disc)) == 1 && e == K(0)
        return true
    else
        if length(factor(disc)) > 1
            println("your candidate factors")
        elseif e != K(0)
            println("your candidate does not vanish on the parametrization")
        end
        return false
    end
end

# Compute "nsamples" samples on pr_2(Y0)
function sample_prY0(pols, nsamples)
    K = base_ring(pols[1])
    vrs = gens(parent(pols[1]))
    n = length(pols) - 1
    T = hcat([[derivative(p, v) for v in vrs] for p in pols]...)
    function Tp(p)
        [Oscar.evaluate(tt, p) for tt in T]
    end
    m = length(vrs) - 1
    randsample = Tp(rand(-100:100, m + 1))
    randsample = matrix_space(K, size(randsample)...)(randsample)
    r = rank(randsample)
    samples = []
    while length(samples) < nsamples
        p = rand(-100:100, m + 1)
        N = nullspace(matrix_space(K, n - r + m + 1, n + 1)(K.(vcat(Tp(K.(p)), rand(-100:100, n - r, n + 1)))))[2]
        if size(N, 2) == 1
            push!(samples, N[:, 1])
        end
    end
    return samples
end

# compute bases of exponents for all multidegrees in the multigrading defined by "multigrading" of total degree deg
function get_basis_monomials(multigrading, deg)
    E = multigrading
    multidegs = lattice_points(deg * convex_hull(E))
    buckets = []
    for i = 1:length(multidegs)
        push!(buckets, compute_bucket(E, multidegs[i]))
    end
    return buckets, multidegs
end

# compute all monomials of a given multidegree with respect to the grading given by E.
function compute_bucket(E, multideg)
    E = hcat(E...)
    A = [-identity_matrix(ZZ, size(E, 2)); matrix_space(ZZ, size(E)...)(E); -matrix_space(ZZ, size(E)...)(E)]
    b = [zeros(Int, size(E, 2)); multideg; -multideg]
    P = polyhedron(A, b)
    return lattice_points(P)
end

# compute (a candidate for) the defining equation of pr_2(Y0) in case it is a hypersurface
function get_prY0(pols; multigrading=[], multideg=[], dmin=1)
    n = length(pols) - 1
    if dim_prY0(pols) != n - 1
        println("prY0 is not a hypersurface")
        return -1
    end
    if isempty(multigrading)
        multigrading = [[1] for i = 1:n+1]
    end
    if isempty(multideg)
        found = false
        deg = dmin
        while !found
            println("looking in degree $deg")
            buckets, multidegs = get_basis_monomials(multigrading, deg)
            nsamples = maximum(length.(buckets)) + 200
            samples = sample_prY0(pols, nsamples)
            for i = 1:length(buckets)
                samples1 = samples[1:length(buckets[i])+200]
                disc, found = get_interpolant(samples1, buckets[i])
                if found
                    return disc
                end
            end
            deg += 1
        end
    else
        mons = compute_bucket(multigrading, multideg)
        nsamples = length(mons) + 200
        samples = sample_prY0(pols, nsamples)
        disc, found = get_interpolant(samples, mons)
        if found
            return disc
        end
    end
end

