# The multidegrees for the discriminants from Table 1 were determined experimentally.
function get_multideg_disc_T1(groupname)
    if groupname == "Z1"
        return 3*[8, 8, 8, 8]
    elseif groupname == "Z2"
        return [18, 6, 6]
    elseif groupname == "dZ2"
        return [12, 12]
    elseif groupname == "Z4"
        return [9]
    elseif groupname == "K4"
        return [9]
    elseif groupname == "nK4"
        return [3, 3]
    elseif groupname == "D4"
        return []
    elseif groupname == "Z3"
        return [18, 6]
    elseif groupname == "S3"
        return [3, 0]
    elseif groupname == "A4"
        return []
    elseif groupname == "S4"
        return []
    elseif groupname == "Z6"
        return [3]
    else
        return []
    end
end


